def build_timeline(metrics, traces, events, slo_window):
    # Align everything to the same window; no aligned timeline, no RCA.
    timeline = {}
    timeline['load'] = metrics.qps(slo_window, by='endpoint')
    timeline['saturation'] = {
        'queue_depth': metrics.p99('queue_wait_ms', slo_window),
        'pool_wait': metrics.p99('pool_checkout_ms', slo_window),
        'cpu': metrics.avg('cpu_util', slo_window),
        'retry_rate': metrics.rate('client_retries_total', slo_window),
    }
    timeline['dependency'] = traces.p99('downstream_latency', slo_window)
    timeline['changes'] = events.filter(kinds=['deploy', 'config', 'autoscale'], window=slo_window)
    # Order matters: what moved FIRST wins.
    return order_by_onset(timeline)

def kill_hypothesis(name, prediction, timeline):
    # Each hypothesis must predict an order. Check it.
    # e.g. db_slow predicts pool_wait rises AFTER db_latency.
    actual = timeline.onset_order()
    holds = prediction == actual
    return {'hypothesis': name, 'holds': holds, 'actual': actual}
